SELECT DISTINCT MMDBDP7_CSHT001_RFS.CD_PLANT, MMDBDP7_CSHT001_RFS.CD_SHIP_TO_LOC, MMDBDP7_CSHT001_RFS.NO_ASN, MMDBDP7_CSHT002_RFS_PART.NO_RFS, MMDBDP7_CSHT001_RFS.CD_AIAG_TRANSIT, [DS_CONV_INITIALS] & [NO_CONVEYANCE] AS CONTAINER_NO, MMDBDP7_CSHT001_RFS.NO_CONV_SEAL_1, MMDBDP7_CSHT001_RFS.NO_CONV_SEAL_2, MMDBDP7_CSHT103_KD_RFS_LBL.NO_LABEL_SERIAL, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_LENGTH, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_WIDTH, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_HEIGHT, [MS_CNTR_LENGTH]*[MS_CNTR_WIDTH]*[MS_CNTR_HEIGHT]/10^6 AS CBM, MMDBDP7_CSHT001_RFS.DT_SHIPPED, MMDBDP7_CPNT023_PART.NO_COMP_PART_NO, MMDBDP7_CPNT023_PART.DS_PART, MMDBDP7_CSHT104_KD_PRT_LBL_VW.QT_ACTUAL_SHIPPED, MMDBDP7_CPNT023_PART.WT_PART, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_WEIGHT, MMDBDP7_CSHT001_RFS.DT_SHIPPED, MMDBDP7_CSHT001_RFS.DS_CONV_INITIALS, MMDBDP7_CSHT001_RFS.NO_CONVEYANCE, MMDBDP7_CSHT001_RFS.CD_CARRIER, MMDBDP7_CMST045_PCT_BUS.CD_SUPPLIER_SHP_FR, MMDBDP7_CSFT050_ML_ASSOC.NO_CNTR_LABEL, MMDBDP7_CMPT045_RLSE_PAR2.CD_CUST_DOCK_10, [MMDBDP7_CSHT001_RFS].[CD_PLANT] & [MMDBDP7_CSHT002_RFS_PART].[NO_RFS] AS Cleaner
FROM ((((((MMDBDP7_CSHT001_RFS INNER JOIN MMDBDP7_CSHT103_KD_RFS_LBL ON (MMDBDP7_CSHT001_RFS.NO_RFS = MMDBDP7_CSHT103_KD_RFS_LBL.NO_RFS) AND (MMDBDP7_CSHT001_RFS.CD_PLANT = MMDBDP7_CSHT103_KD_RFS_LBL.CD_PLANT)) INNER JOIN MMDBDP7_CSHT104_KD_PRT_LBL_VW ON (MMDBDP7_CSHT103_KD_RFS_LBL.NO_LABEL_SERIAL = MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_LABEL_SERIAL) AND (MMDBDP7_CSHT103_KD_RFS_LBL.NO_RFS = MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_RFS) AND (MMDBDP7_CSHT103_KD_RFS_LBL.CD_PLANT = MMDBDP7_CSHT104_KD_PRT_LBL_VW.CD_PLANT)) INNER JOIN MMDBDP7_CSHT002_RFS_PART ON (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_PART_SUFFIX = MMDBDP7_CSHT002_RFS_PART.NO_PART_SUFFIX) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_PART_PREFIX = MMDBDP7_CSHT002_RFS_PART.NO_PART_PREFIX) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_PART_BASE = MMDBDP7_CSHT002_RFS_PART.NO_PART_BASE) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_RFS = MMDBDP7_CSHT002_RFS_PART.NO_RFS) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.CD_PLANT = MMDBDP7_CSHT002_RFS_PART.CD_PLANT)) INNER JOIN MMDBDP7_CPNT023_PART ON (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_PART_SUFFIX = MMDBDP7_CPNT023_PART.NO_PART_SUFFIX) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_PART_PREFIX = MMDBDP7_CPNT023_PART.NO_PART_PREFIX) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_PART_BASE = MMDBDP7_CPNT023_PART.NO_PART_BASE) AND (MMDBDP7_CSHT104_KD_PRT_LBL_VW.CD_PLANT = MMDBDP7_CPNT023_PART.CD_PLANT)) INNER JOIN MMDBDP7_CMST045_PCT_BUS ON (MMDBDP7_CPNT023_PART.NO_PART_SUFFIX = MMDBDP7_CMST045_PCT_BUS.NO_PART_SUFFIX) AND (MMDBDP7_CPNT023_PART.NO_PART_PREFIX = MMDBDP7_CMST045_PCT_BUS.NO_PART_PREFIX) AND (MMDBDP7_CPNT023_PART.NO_PART_BASE = MMDBDP7_CMST045_PCT_BUS.NO_PART_BASE) AND (MMDBDP7_CPNT023_PART.CD_PLANT = MMDBDP7_CMST045_PCT_BUS.CD_PLANT)) INNER JOIN MMDBDP7_CSFT050_ML_ASSOC ON MMDBDP7_CSHT104_KD_PRT_LBL_VW.NO_LABEL_SERIAL = MMDBDP7_CSFT050_ML_ASSOC.NO_MASTER_LABEL) INNER JOIN MMDBDP7_CMPT045_RLSE_PAR2 ON (MMDBDP7_CSHT001_RFS.CD_SHIP_TO_LOC = MMDBDP7_CMPT045_RLSE_PAR2.CD_CUSTOMER) AND (MMDBDP7_CPNT023_PART.NO_PART_SUFFIX = MMDBDP7_CMPT045_RLSE_PAR2.NO_PART_SUFFIX) AND (MMDBDP7_CPNT023_PART.NO_PART_PREFIX = MMDBDP7_CMPT045_RLSE_PAR2.NO_PART_PREFIX) AND (MMDBDP7_CPNT023_PART.NO_PART_BASE = MMDBDP7_CMPT045_RLSE_PAR2.NO_PART_BASE) AND (MMDBDP7_CPNT023_PART.CD_PLANT = MMDBDP7_CMPT045_RLSE_PAR2.CD_PLANT)
GROUP BY MMDBDP7_CSHT001_RFS.CD_PLANT, MMDBDP7_CSHT001_RFS.CD_SHIP_TO_LOC, MMDBDP7_CSHT001_RFS.NO_ASN, MMDBDP7_CSHT002_RFS_PART.NO_RFS, MMDBDP7_CSHT001_RFS.CD_AIAG_TRANSIT, [DS_CONV_INITIALS] & [NO_CONVEYANCE], MMDBDP7_CSHT001_RFS.NO_CONV_SEAL_1, MMDBDP7_CSHT001_RFS.NO_CONV_SEAL_2, MMDBDP7_CSHT103_KD_RFS_LBL.NO_LABEL_SERIAL, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_LENGTH, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_WIDTH, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_HEIGHT, [MS_CNTR_LENGTH]*[MS_CNTR_WIDTH]*[MS_CNTR_HEIGHT]/10^6, MMDBDP7_CPNT023_PART.NO_COMP_PART_NO, MMDBDP7_CPNT023_PART.DS_PART, MMDBDP7_CSHT104_KD_PRT_LBL_VW.QT_ACTUAL_SHIPPED, MMDBDP7_CPNT023_PART.WT_PART, MMDBDP7_CSHT103_KD_RFS_LBL.MS_CNTR_WEIGHT, MMDBDP7_CSHT001_RFS.DT_SHIPPED, MMDBDP7_CSHT001_RFS.DS_CONV_INITIALS, MMDBDP7_CSHT001_RFS.NO_CONVEYANCE, MMDBDP7_CSHT001_RFS.CD_CARRIER, MMDBDP7_CMST045_PCT_BUS.CD_SUPPLIER_SHP_FR, MMDBDP7_CSFT050_ML_ASSOC.NO_CNTR_LABEL, MMDBDP7_CMPT045_RLSE_PAR2.CD_CUST_DOCK_10, [MMDBDP7_CSHT001_RFS].[CD_PLANT] & [MMDBDP7_CSHT002_RFS_PART].[NO_RFS], MMDBDP7_CSHT002_RFS_PART.CS_TRANSFER_PRICE, MMDBDP7_CSHT001_RFS.TM_SHIPPED, MMDBDP7_CSHT001_RFS.DT_SHIPPED
HAVING (((MMDBDP7_CSHT001_RFS.CD_PLANT) Like "1688E" Or (MMDBDP7_CSHT001_RFS.CD_PLANT)="1688F" Or (MMDBDP7_CSHT001_RFS.CD_PLANT)="1688K" Or (MMDBDP7_CSHT001_RFS.CD_PLANT)="1688P" Or (MMDBDP7_CSHT001_RFS.CD_PLANT)="HQHNA" Or (MMDBDP7_CSHT001_RFS.CD_PLANT)="1055P") AND ((MMDBDP7_CSHT001_RFS.CD_AIAG_TRANSIT)<>"A ") AND ((MMDBDP7_CSHT001_RFS.DT_SHIPPED)>=DateSerial(Year(Date()),Month(Date())-1,1) And (MMDBDP7_CSHT001_RFS.DT_SHIPPED)<DateSerial(Year(Date()),Month(Date()),1)))
ORDER BY MMDBDP7_CSHT001_RFS.DT_SHIPPED;